SELECT sales_line.order_number, sales_line.line_no, sales_line.item, sales_line.quantity, COALESCE(on_hand.quantity_on_hand, 0) AS on_hand, outage.warehouse IS NOT NULL AS outage, sales_line.quantity - COALESCE(on_hand.quantity_on_hand, 0) AS short FROM "order" JOIN sales_line ON sales_line.order_number = "order".order_number LEFT JOIN (SELECT inventory.item, inventory.warehouse, inventory.quantity_on_hand, ROW_NUMBER() OVER (PARTITION BY inventory.item, inventory.warehouse ORDER BY inventory.as_of_date DESC) AS rn FROM inventory) on_hand ON on_hand.item = sales_line.item AND on_hand.warehouse = sales_line.warehouse AND on_hand.rn = 1 LEFT JOIN (SELECT warehouse_outage.warehouse FROM warehouse_outage WHERE warehouse_outage.from_date <= {as_of} AND warehouse_outage.to_date >= {as_of}) outage ON outage.warehouse = sales_line.warehouse WHERE "order".state IN ('placed', 'held') AND (outage.warehouse IS NOT NULL OR COALESCE(on_hand.quantity_on_hand, 0) < sales_line.quantity)
